import re, urllib.request, urllib.parse, http.cookiejar, json, sys
BASE="http://openproject.io"
cookies={}
def req(method, path, data=None, headers=None):
    h = {"Cookie": "; ".join(f"{k}={v}" for k,v in cookies.items())}
    if headers: h.update(headers)
    r = urllib.request.Request(BASE+path, data=data, method=method, headers=h)
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *a, **k): return None
    opener = urllib.request.build_opener(NoRedirect)
    try:
        resp = opener.open(r, timeout=30)
    except urllib.error.HTTPError as e:
        resp = e
    for sc in resp.headers.get_all("Set-Cookie") or []:
        k,v = sc.split(";")[0].split("=",1)
        cookies[k]=v
    return resp.status, resp.headers, resp.read().decode("utf-8","replace")
s,h,body = req("GET","/login")
forms = re.findall(r'<form[^>]*action="/login"[^>]*>(.*?)</form>', body, re.S)
tok = None
for f in forms:
    if 'username' in f:
        tok = re.search(r'name="authenticity_token" value="([^"]*)"', f).group(1)
print("token", tok[:10])
data = urllib.parse.urlencode({"authenticity_token":tok,"username":"admin","password":"Admin123!"}).encode()
s,h,body = req("POST","/login",data,{"Content-Type":"application/x-www-form-urlencoded","Origin":BASE,"Referer":BASE+"/login"})
print(s, h.get("Location"))
s,h,body = req("GET","/api/v3/users/me",headers={"X-Requested-With":"XMLHttpRequest"})
print(s, body[:300])
json.dump(cookies, open("/tmp/op_cookies.json","w"))
EOF
