import json, sys, urllib.request
URL="http://localhost:8108/mcp"
_sid=None
_id=0
def _post(payload):
    global _sid
    h={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}
    if _sid: h["mcp-session-id"]=_sid
    r=urllib.request.Request(URL,data=json.dumps(payload).encode(),headers=h,method="POST")
    resp=urllib.request.urlopen(r,timeout=120)
    sid=resp.headers.get("mcp-session-id")
    if sid: _sid=sid
    body=resp.read().decode()
    out=[]
    for line in body.splitlines():
        if line.startswith("data:"):
            out.append(json.loads(line[5:].strip()))
    if not out and body.strip():
        try: out.append(json.loads(body))
        except Exception: pass
    return out
def init():
    global _id
    _id+=1
    r=_post({"jsonrpc":"2.0","id":_id,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"pi","version":"1.0"}}})
    _post({"jsonrpc":"2.0","method":"notifications/initialized"})
    return r
def call(method, params=None):
    global _id
    _id+=1
    return _post({"jsonrpc":"2.0","id":_id,"method":method,"params":params or {}})
def tool(name, **args):
    r=call("tools/call",{"name":name,"arguments":args})
    return r
if __name__=="__main__":
    init()
    if sys.argv[1]=="list":
        r=call("tools/list")
        for t in r[0]["result"]["tools"]:
            print("==",t["name"]); print(t.get("description","")[:600]); print(json.dumps(t.get("inputSchema",{}).get("properties",{}))[:1500]); print()
    else:
        name=sys.argv[1]; args=json.loads(sys.argv[2]) if len(sys.argv)>2 else {}
        r=tool(name,**args)
        for m in r:
            if "result" in m:
                for c in m["result"].get("content",[]):
                    print(c.get("text",c))
                if m["result"].get("structuredContent") and not m["result"].get("content"):
                    print(json.dumps(m["result"]["structuredContent"],indent=1))
            else:
                print(json.dumps(m)[:3000])
EOF
