        for p in s.header.paragraphs:
            if p.text.strip(): print("[HEADER]", p.text)
        for p in s.footer.paragraphs:
            if p.text.strip(): print("[FOOTER]", p.text)
    body = d.element.body
    for child in body.iterchildren():
        tag = child.tag.split('}')[1]
        if tag == 'p':
            p = docx.text.paragraph.Paragraph(child, d)
            if p.text.strip(): print(f"[{p.style.name}] {p.text}")
        elif tag == 'tbl':
            t = docx.table.Table(child, d)
            print("[TABLE]")
            for r in t.rows:
                cells = []
                prev = None
                for c in r.cells:
                    if c._tc is prev: continue
                    prev = c._tc
                    cells.append(c.text.replace("\n"," / "))
                print("  | " + " | ".join(cells))
    # comments / footnotes
    try:
        part = d.part
        for rel in part.rels.values():
            if "comments" in rel.reltype or "footnotes" in rel.reltype or "endnotes" in rel.reltype:
                print("REL:", rel.reltype)
                print(rel.target_part.blob.decode('utf8')[:5000])
    except Exception as e:
        print("err", e)
